import { loadConfig, type McpConfig } from "../config.js";
import type { GraphProvider } from "../providers/GraphProvider.js";
import { BridgeClient } from "../providers/bridge/client.js";
import { createObsidianBridgeProvider } from "../providers/bridge/ObsidianBridgeProvider.js";

export type ServerContext = {
  config: McpConfig;
  bridgeClient: BridgeClient;
  bridgeProvider: GraphProvider;
  isBridgeUp: () => Promise<boolean>;
};

export const createServerContext = (): ServerContext => {
  const config = loadConfig();
  const bridgeClient = new BridgeClient({ baseUrl: config.bridgeUrl });
  const bridgeProvider = createObsidianBridgeProvider(bridgeClient);

  return {
    config,
    bridgeClient,
    bridgeProvider,
    isBridgeUp: () => bridgeClient.isReachable(),
  };
};

