import type { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
import { z } from "zod";
import type { ServerContext } from "../server/context.js";
import { resolveLocalReadProvider } from "./localBridge.js";
import { errorResult, jsonResult } from "./toolResult.js";

const SpaceSchema = z
  .string()
  .optional()
  .describe('Graph scope. Default "mine" (your vault).');

const withLocalRead = async <T>(
  ctx: ServerContext,
  space: string | undefined,
  run: (provider: Awaited<ReturnType<typeof resolveLocalReadProvider>> & { ok: true }) => Promise<T>,
): Promise<T | ReturnType<typeof errorResult>> => {
  const resolution = await resolveLocalReadProvider(ctx, space);
  if (!resolution.ok) {
    return errorResult(resolution.error);
  }
  return run(resolution);
};

export const registerReadTools = (
  server: McpServer,
  ctx: ServerContext,
): void => {
  server.tool(
    "get_node_types",
    "Get discourse node types configured in your Obsidian vault.",
    { space: SpaceSchema },
    async ({ space }) =>
      withLocalRead(ctx, space, async ({ provider }) => {
        const nodeTypes = await provider.getNodeTypes();
        return jsonResult({ nodeTypes });
      }),
  );

  server.tool(
    "get_relation_types",
    "Get relation types (supports, refutes, etc.) configured in your vault.",
    { space: SpaceSchema },
    async ({ space }) =>
      withLocalRead(ctx, space, async ({ provider }) => {
        const relationTypes = await provider.getRelationTypes();
        return jsonResult({ relationTypes });
      }),
  );

  server.tool(
    "get_discourse_relations",
    "Get allowed discourse relation triples (source type → relation → destination type).",
    { space: SpaceSchema },
    async ({ space }) =>
      withLocalRead(ctx, space, async ({ provider }) => {
        const discourseRelations = await provider.getDiscourseRelations();
        return jsonResult({ discourseRelations });
      }),
  );

  server.tool(
    "search_nodes",
    "Search discourse nodes in your vault by title.",
    {
      query: z.string().describe("Title search string (minimum 2 characters)."),
      nodeTypeId: z
        .string()
        .optional()
        .describe("Optional node type id filter."),
      limit: z
        .number()
        .int()
        .positive()
        .optional()
        .describe("Maximum number of results to return."),
      space: SpaceSchema,
    },
    async ({ query, nodeTypeId, limit, space }) =>
      withLocalRead(ctx, space, async ({ provider }) => {
        const result = await provider.searchNodes({
          query,
          nodeTypeId,
          limit,
        });
        return jsonResult(result);
      }),
  );

  server.tool(
    "get_node",
    "Get a discourse node by instance id (includes body and metadata).",
    {
      nodeId: z
        .string()
        .describe("Node instance id or vault endpoint identifier."),
      space: SpaceSchema,
    },
    async ({ nodeId, space }) =>
      withLocalRead(ctx, space, async ({ provider }) => {
        const node = await provider.getNode(nodeId);
        if (!node) {
          return errorResult(`Node not found: ${nodeId}`);
        }
        return jsonResult({ node });
      }),
  );

  server.tool(
    "get_relations",
    "Get all relations involving a discourse node.",
    {
      nodeId: z.string().describe("Node instance id."),
      space: SpaceSchema,
    },
    async ({ nodeId, space }) =>
      withLocalRead(ctx, space, async ({ provider }) => {
        const relations = await provider.getRelations(nodeId);
        return jsonResult({ relations });
      }),
  );

  server.tool(
    "get_discourse_context",
    "Get a node plus its relations and related nodes (1-hop discourse context).",
    {
      nodeId: z.string().describe("Node instance id."),
      space: SpaceSchema,
    },
    async ({ nodeId, space }) =>
      withLocalRead(ctx, space, async ({ provider }) => {
        const context = await provider.getDiscourseContext(nodeId);
        if (!context) {
          return errorResult(`Node not found: ${nodeId}`);
        }
        return jsonResult(context);
      }),
  );
};
