import type { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
import { z } from "zod";
import type { BridgeClient } from "../providers/bridge/client.js";
import type { ServerContext } from "../server/context.js";
import { resolveLocalWriteBridge } from "./localBridge.js";
import { errorResult, jsonResult } from "./toolResult.js";
import {
  DEFAULT_WRITE_WAIT_TIMEOUT_MS,
  pollWriteBatchUntilResolved,
} from "./writeApproval.js";
import {
  toBridgeWriteOperation,
  WaitForApprovalSchema,
  WaitTimeoutSecondsSchema,
  WriteOperationSchema,
} from "./writeSchemas.js";

const APPROVAL_HINT =
  "Approve or reject in Obsidian (bottom-right pill). " +
  "Call again with waitForApproval: true or poll get_pending_write.";

type ProposeResult = {
  ok: true;
  status: "pending" | "approved" | "rejected" | "timeout";
  batchId: string;
  createdAt: string;
  expiresAt?: string;
  operationCount: number;
  message?: string;
  batch?: unknown;
};

const withLocalWrite = async <T>(
  ctx: ServerContext,
  run: (client: BridgeClient) => Promise<T>,
): Promise<T | ReturnType<typeof errorResult>> => {
  const resolution = await resolveLocalWriteBridge(ctx);
  if (!resolution.ok) {
    return errorResult(resolution.error);
  }
  return run(resolution.client);
};

const proposeAndMaybeWait = async ({
  client,
  operations,
  label,
  waitForApproval,
  waitTimeoutSeconds,
}: {
  client: BridgeClient;
  operations: ReturnType<typeof toBridgeWriteOperation>[];
  label?: string;
  waitForApproval?: boolean;
  waitTimeoutSeconds?: number;
}): Promise<ProposeResult | ReturnType<typeof errorResult>> => {
  const proposed = await client.proposeWrite({ operations, label });

  if (!waitForApproval) {
    return {
      ok: true,
      status: "pending",
      batchId: proposed.batchId,
      createdAt: proposed.createdAt,
      expiresAt: proposed.expiresAt,
      operationCount: proposed.operationCount,
      message: APPROVAL_HINT,
    };
  }

  const pollResult = await pollWriteBatchUntilResolved({
    client,
    batchId: proposed.batchId,
    timeoutMs: (waitTimeoutSeconds ?? 120) * 1_000,
  });

  switch (pollResult.status) {
    case "approved":
      return {
        ok: true,
        status: "approved",
        batchId: proposed.batchId,
        createdAt: proposed.createdAt,
        operationCount: proposed.operationCount,
        batch: pollResult.batch,
        message: "Write batch approved and applied to your vault.",
      };
    case "rejected":
      return {
        ok: true,
        status: "rejected",
        batchId: proposed.batchId,
        createdAt: proposed.createdAt,
        operationCount: proposed.operationCount,
        batch: pollResult.batch,
        message: "Write batch was rejected. No changes were made.",
      };
    case "timeout":
      return {
        ok: true,
        status: "timeout",
        batchId: proposed.batchId,
        createdAt: proposed.createdAt,
        expiresAt: proposed.expiresAt,
        operationCount: proposed.operationCount,
        message:
          `Timed out after ${waitTimeoutSeconds ?? DEFAULT_WRITE_WAIT_TIMEOUT_MS / 1_000}s ` +
          "waiting for approval. The proposal may still be pending in Obsidian.",
        batch: pollResult.lastKnown ?? undefined,
      };
    case "not_found":
      return errorResult(
        `Write batch not found after propose: ${proposed.batchId}`,
      );
  }
};

const sharedWaitFields = {
  waitForApproval: WaitForApprovalSchema,
  waitTimeoutSeconds: WaitTimeoutSecondsSchema,
};

export const registerWriteTools = (
  server: McpServer,
  ctx: ServerContext,
): void => {
  server.tool(
    "create_node",
    "Propose creating a new discourse node. Does not write until approved in Obsidian.",
    {
      nodeTypeId: z.string().describe("Discourse node type id."),
      content: z
        .string()
        .min(1)
        .describe("Title text (fills the node type format {content} slot)."),
      body: z.string().optional().describe("Optional markdown body."),
      label: z
        .string()
        .optional()
        .describe("Optional short label shown in the approval UI."),
      ...sharedWaitFields,
    },
    async ({ nodeTypeId, content, body, label, waitForApproval, waitTimeoutSeconds }) =>
      withLocalWrite(ctx, async (client) => {
        const result = await proposeAndMaybeWait({
          client,
          label,
          waitForApproval,
          waitTimeoutSeconds,
          operations: [
            toBridgeWriteOperation({
              kind: "create_node",
              nodeTypeId,
              content,
              body,
            }),
          ],
        });
        return jsonResult(result);
      }),
  );

  server.tool(
    "update_node",
    "Propose updating an existing discourse node. Does not write until approved in Obsidian.",
    {
      nodeInstanceId: z
        .string()
        .optional()
        .describe("Target node instance id."),
      nodeId: z.string().optional().describe("Alias for nodeInstanceId."),
      filename: z
        .string()
        .optional()
        .describe("Target vault path or note basename."),
      path: z.string().optional().describe("Alias for filename."),
      title: z
        .string()
        .optional()
        .describe("New discourse title; renames the note file."),
      content: z.string().optional().describe("New markdown body."),
      body: z.string().optional().describe("Alias for content."),
      label: z.string().optional(),
      ...sharedWaitFields,
    },
    async (args) =>
      withLocalWrite(ctx, async (client) => {
        try {
          const operation = toBridgeWriteOperation({
            kind: "update_node",
            nodeInstanceId: args.nodeInstanceId,
            nodeId: args.nodeId,
            filename: args.filename,
            path: args.path,
            title: args.title,
            content: args.content,
            body: args.body,
          });
          const result = await proposeAndMaybeWait({
            client,
            label: args.label,
            waitForApproval: args.waitForApproval,
            waitTimeoutSeconds: args.waitTimeoutSeconds,
            operations: [operation],
          });
          return jsonResult(result);
        } catch (error) {
          return errorResult(
            error instanceof Error ? error.message : String(error),
          );
        }
      }),
  );

  server.tool(
    "create_relation",
    "Propose a relation between two discourse nodes. Does not write until approved in Obsidian.",
    {
      sourceId: z.string().describe("Source node instance id."),
      destinationId: z.string().describe("Destination node instance id."),
      relationTypeId: z.string().describe("Relation type id."),
      label: z.string().optional(),
      ...sharedWaitFields,
    },
    async ({
      sourceId,
      destinationId,
      relationTypeId,
      label,
      waitForApproval,
      waitTimeoutSeconds,
    }) =>
      withLocalWrite(ctx, async (client) => {
        const result = await proposeAndMaybeWait({
          client,
          label,
          waitForApproval,
          waitTimeoutSeconds,
          operations: [
            toBridgeWriteOperation({
              kind: "create_relation",
              sourceId,
              destinationId,
              relationTypeId,
            }),
          ],
        });
        return jsonResult(result);
      }),
  );

  server.tool(
    "propose_write_batch",
    "Propose multiple discourse graph writes as one batch. Does not write until approved in Obsidian. " +
      "Propose all batches before waiting — the user can approve or reject each in Obsidian.",
    {
      operations: z
        .array(WriteOperationSchema)
        .min(1)
        .describe("One or more write operations to buffer together."),
      label: z
        .string()
        .optional()
        .describe("Optional short label for the approval UI."),
      ...sharedWaitFields,
    },
    async ({ operations, label, waitForApproval, waitTimeoutSeconds }) =>
      withLocalWrite(ctx, async (client) => {
        try {
          const result = await proposeAndMaybeWait({
            client,
            label,
            waitForApproval,
            waitTimeoutSeconds,
            operations: operations.map(toBridgeWriteOperation),
          });
          return jsonResult(result);
        } catch (error) {
          return errorResult(
            error instanceof Error ? error.message : String(error),
          );
        }
      }),
  );

  server.tool(
    "get_pending_write",
    "Check whether a proposed write batch is still pending, approved, or rejected.",
    {
      batchId: z.string().describe("Batch id returned from a propose/write tool."),
    },
    async ({ batchId }) =>
      withLocalWrite(ctx, async (client) => {
        const { batch } = await client.getPendingWrite(batchId);
        if (!batch) {
          return errorResult(`Write batch not found: ${batchId}`);
        }
        return jsonResult({ batch });
      }),
  );
};
