import {
  BRIDGE_PATHS,
  type BridgeContext,
  type BridgeHealth,
  type BridgeNodeContextResponse,
  type BridgeNodePayload,
  type BridgeRelationPayload,
  type BridgeNodeSummary,
} from "./types.js";
import {
  BRIDGE_WRITE_PATHS,
  type BridgePendingWriteResponse,
  type BridgePendingWritesListResponse,
  type BridgeProposeWriteResponse,
  type BridgeWriteOperation,
} from "./writeTypes.js";

export type BridgeClientOptions = {
  baseUrl: string;
  fetchImpl?: typeof fetch;
  requestTimeoutMs?: number;
};

export class BridgeHttpError extends Error {
  readonly status: number;
  readonly responseBody: unknown;

  constructor(status: number, responseBody: unknown) {
    super(`Bridge request failed with status ${status}`);
    this.name = "BridgeHttpError";
    this.status = status;
    this.responseBody = responseBody;
  }
}

export class BridgeClient {
  private readonly baseUrl: string;
  private readonly fetchImpl: typeof fetch;
  private readonly requestTimeoutMs: number;

  constructor(options: BridgeClientOptions) {
    this.baseUrl = options.baseUrl.replace(/\/$/, "");
    this.fetchImpl = options.fetchImpl ?? fetch;
    this.requestTimeoutMs = options.requestTimeoutMs ?? 10_000;
  }

  async isReachable(): Promise<boolean> {
    try {
      const health = await this.getHealth();
      return health.ok === true;
    } catch {
      return false;
    }
  }

  async getHealth(): Promise<BridgeHealth> {
    return this.getJson<BridgeHealth>(BRIDGE_PATHS.health);
  }

  async getContext(): Promise<BridgeContext> {
    return this.getJson<BridgeContext>(BRIDGE_PATHS.context);
  }

  async getNodeTypes(): Promise<
    Array<{
      id: string;
      name: string;
      format: string;
      description?: string;
      color?: string;
      tag?: string;
    }>
  > {
    const body = await this.getJson<{ nodeTypes: Array<{
      id: string;
      name: string;
      format: string;
      description?: string;
      color?: string;
      tag?: string;
    }> }>(BRIDGE_PATHS.nodeTypes);
    return body.nodeTypes;
  }

  async getRelationTypes(): Promise<
    Array<{
      id: string;
      label: string;
      complement: string;
      color?: string;
    }>
  > {
    const body = await this.getJson<{
      relationTypes: Array<{
        id: string;
        label: string;
        complement: string;
        color?: string;
      }>;
    }>(BRIDGE_PATHS.relationTypes);
    return body.relationTypes;
  }

  async getDiscourseRelations(): Promise<
    Array<{
      id: string;
      sourceId: string;
      destinationId: string;
      relationshipTypeId: string;
    }>
  > {
    const body = await this.getJson<{
      discourseRelations: Array<{
        id: string;
        sourceId: string;
        destinationId: string;
        relationshipTypeId: string;
      }>;
    }>(BRIDGE_PATHS.discourseRelations);
    return body.discourseRelations;
  }

  async searchNodes(params: {
    query: string;
    nodeTypeId?: string;
  }): Promise<BridgeNodeSummary[]> {
    const body = await this.postJson<{ nodes: BridgeNodeSummary[] }>(
      BRIDGE_PATHS.search,
      params,
    );
    return body.nodes;
  }

  async getNode(nodeId: string): Promise<BridgeNodePayload | null> {
    try {
      const body = await this.getJson<{ node: BridgeNodePayload }>(
        `/node/${encodeURIComponent(nodeId)}`,
      );
      return body.node;
    } catch (error) {
      if (error instanceof BridgeHttpError && error.status === 404) {
        return null;
      }
      throw error;
    }
  }

  async getNodeRelations(nodeId: string): Promise<BridgeRelationPayload[]> {
    const body = await this.getJson<{ relations: BridgeRelationPayload[] }>(
      `/node/${encodeURIComponent(nodeId)}/relations`,
    );
    return body.relations;
  }

  async getNodeContext(
    nodeId: string,
  ): Promise<BridgeNodeContextResponse | null> {
    try {
      return await this.getJson<BridgeNodeContextResponse>(
        `/node/${encodeURIComponent(nodeId)}/context`,
      );
    } catch (error) {
      if (error instanceof BridgeHttpError && error.status === 404) {
        return null;
      }
      throw error;
    }
  }

  async proposeWrite(input: {
    operations: BridgeWriteOperation[];
    label?: string;
  }): Promise<BridgeProposeWriteResponse> {
    return this.postJson<BridgeProposeWriteResponse>(
      BRIDGE_WRITE_PATHS.proposeWrite,
      input,
    );
  }

  async getPendingWrite(batchId: string): Promise<BridgePendingWriteResponse> {
    try {
      return await this.getJson<BridgePendingWriteResponse>(
        BRIDGE_WRITE_PATHS.pendingWrite(batchId),
      );
    } catch (error) {
      if (error instanceof BridgeHttpError && error.status === 404) {
        return { batch: null };
      }
      throw error;
    }
  }

  async listPendingWrites(): Promise<BridgePendingWritesListResponse> {
    return this.getJson<BridgePendingWritesListResponse>(
      BRIDGE_WRITE_PATHS.pendingWrites,
    );
  }

  private async getJson<T>(path: string): Promise<T> {
    const response = await this.fetchImpl(`${this.baseUrl}${path}`, {
      method: "GET",
      headers: { Accept: "application/json" },
      signal: AbortSignal.timeout(this.requestTimeoutMs),
    });
    return this.parseJsonResponse<T>(response);
  }

  private async postJson<T>(path: string, payload: unknown): Promise<T> {
    const response = await this.fetchImpl(`${this.baseUrl}${path}`, {
      method: "POST",
      headers: {
        Accept: "application/json",
        "Content-Type": "application/json",
      },
      body: JSON.stringify(payload),
      signal: AbortSignal.timeout(this.requestTimeoutMs),
    });
    return this.parseJsonResponse<T>(response);
  }

  private async parseJsonResponse<T>(response: Response): Promise<T> {
    const text = await response.text();
    const body = text ? (JSON.parse(text) as unknown) : null;

    if (!response.ok) {
      throw new BridgeHttpError(response.status, body);
    }

    return body as T;
  }
}

