import type { GraphSpace, ProviderKind, ReadSource } from "../domain/types.js";

export type NormalizedSpace =
  | { kind: "mine" }
  | { kind: "all" }
  | { kind: "specific"; spaceId: number }
  | { kind: "specific"; spaceUrl: string };

export type ScopeRouterInput = {
  space?: GraphSpace | string;
  source?: ReadSource;
  bridgeUp: boolean;
  supabaseConfigured: boolean;
};

export type ScopeRouterResult =
  | { ok: true; provider: ProviderKind }
  | { ok: false; error: string };

export class ScopeRouterError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "ScopeRouterError";
  }
}

export const normalizeSpace = (space?: GraphSpace | string): NormalizedSpace => {
  if (space === undefined || space === "mine") {
    return { kind: "mine" };
  }
  if (space === "all") {
    return { kind: "all" };
  }
  if (typeof space === "object" && "spaceId" in space) {
    return { kind: "specific", spaceId: space.spaceId };
  }
  if (typeof space === "object" && "spaceUrl" in space) {
    return { kind: "specific", spaceUrl: space.spaceUrl };
  }
  if (typeof space === "string") {
    const asNumber = Number(space);
    if (!Number.isNaN(asNumber) && space.trim() !== "") {
      return { kind: "specific", spaceId: asNumber };
    }
    return { kind: "specific", spaceUrl: space };
  }
  return { kind: "mine" };
};

const isCrossGraphSpace = (normalized: NormalizedSpace): boolean =>
  normalized.kind === "all" ||
  (normalized.kind === "specific" &&
    ("spaceId" in normalized || "spaceUrl" in normalized));

/**
 * Pick the backend for a read operation.
 * - `mine` + bridge up -> bridge (freshest)
 * - `mine` + bridge down + supabase -> supabase fallback
 * - cross-graph -> supabase only
 */
export const resolveReadProvider = (
  input: ScopeRouterInput,
): ScopeRouterResult => {
  const source = input.source ?? "auto";
  const normalized = normalizeSpace(input.space);

  if (source === "local") {
    if (!input.bridgeUp) {
      return {
        ok: false,
        error:
          "Local bridge is not reachable. Start Obsidian with the Discourse Graph plugin.",
      };
    }
    return { ok: true, provider: "bridge" };
  }

  if (source === "remote") {
    if (!input.supabaseConfigured) {
      return {
        ok: false,
        error: "Supabase is not configured. Set DG_SPACE_URL and DG_SPACE_PASSWORD.",
      };
    }
    return { ok: true, provider: "supabase" };
  }

  // auto
  if (isCrossGraphSpace(normalized)) {
    if (!input.supabaseConfigured) {
      return {
        ok: false,
        error:
          "Cross-graph reads require Supabase. Enable sync or configure space credentials.",
      };
    }
    return { ok: true, provider: "supabase" };
  }

  // mine
  if (input.bridgeUp) {
    return { ok: true, provider: "bridge" };
  }
  if (input.supabaseConfigured) {
    return { ok: true, provider: "supabase" };
  }
  return {
    ok: false,
    error:
      "Obsidian bridge is not reachable and Supabase is not configured.",
  };
};

/** Writes always target the local vault via the bridge (v1). */
export const resolveWriteProvider = (
  bridgeUp: boolean,
): ScopeRouterResult => {
  if (!bridgeUp) {
    return {
      ok: false,
      error:
        "Obsidian must be running to write. Start Obsidian with the Discourse Graph plugin.",
    };
  }
  return { ok: true, provider: "bridge" };
};

export const assertReadProvider = (input: ScopeRouterInput): ProviderKind => {
  const result = resolveReadProvider(input);
  if (!result.ok) {
    throw new ScopeRouterError(result.error);
  }
  return result.provider;
};

export const assertWriteProvider = (bridgeUp: boolean): ProviderKind => {
  const result = resolveWriteProvider(bridgeUp);
  if (!result.ok) {
    throw new ScopeRouterError(result.error);
  }
  return result.provider;
};
